    it("a single staff → base premium 80 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it("a single potion → base premium 40 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 49 }] });
    });
    it("a single rune → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
    it("a single moonstone → base premium 25 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
  });

  describe("quote — building block of 3 alike components", () => {
    it("2 runes → 50 G base premium", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "rune" }, { type: "rune" }] },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 60 }] });
    });
    it("3 runes → 60 G base premium (block applies)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("7 runes → 175 G base premium", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: Array.from({ length: 7 }, () => ({ type: "rune" })),
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 198 }] });
    });
    it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 88 }] });
    });
    it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "rune" },
              { type: "rune" },
              { type: "rune" },
              { type: "moonstone" },
              { type: "moonstone" },
              { type: "moonstone" },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 137 }] });
    });
  });

  describe("quote — item-specific modifiers", () => {
    it("cursed sword adds a 50 % risk surcharge of its own base premium", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "sword", material: "steel", enchantment: 3, cursed: true },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 165 }] });
    });
    it("sword with enchantment 5 adds a 30 % high-enchantment surcharge (threshold is inclusive)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [
              { type: "sword", material: "steel", enchantment: 5, cursed: false },
            ],
          },
        ],
      });

      expect(result).toEqual({ results: [{ premium: 145 }] });
    });
    it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 gets both surcharges");
    it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (of the sword only) → 210 G before further modifiers and fee");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("every quote carries a 10 % first insurance surcharge on the policy base premium");
    it.todo("the second and each later quote in a scenario gets a 15 % follow-up contract discount");
    it.todo("a 5 G processing fee is added to every premium, at the very end");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (no enchantment or material)");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins, then deductible)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold is inclusive)");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible per damaged item)");
  });

  describe("claim — payout rounding", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (block discount affects the premium only)");
    it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword insured (cap 2000 G), two successive claims of 1500 G → second payout 600 G, remainingCap 0 G");
  });

  describe("multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("a dragon attack damaging both swords → two damage entries, each with its own deductible");
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → the whole claim is rejected");
  });

  describe("errors", () => {
    it.todo("quote includes an item with an unknown type (broomstick) → error, no results");
    it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results: [...]} to stdout, one result per step in order");
    it.todo("exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
  });
});

