const BLOCK_BASE_PREMIUM = 60;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;

const basePremiumOf = (item: Item): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];

interface RiskSurcharge {
  appliesTo: (item: Item) => boolean;
  percent: number;
}

const RISK_SURCHARGES: RiskSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
  {
    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
  },
];

const itemSurcharge = (item: Item): number =>
  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
    (sum, surcharge) => sum + percentOf(basePremiumOf(item), surcharge.percent),
    0,
  );

const policySurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

const groupByType = (items: Item[]): Item[][] => [
  ...items
    .reduce(
      (groups, item) =>
        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
      new Map<string, Item[]>(),
    )
    .values(),
];

const basePremiumOfGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : group.reduce((sum, item) => sum + basePremiumOf(item), 0);

const policyBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = policyBasePremium(items);
  const loyaltyDiscount = isLoyal(customer)
    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
    : 0;
  const premiumBeforeFee =
    policyBase +
    policySurcharges(items) -
    loyaltyDiscount +
    percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote")
    return { premium: quotePremium(step.items, customer) };
  throw new Error("claim steps are not implemented yet");
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

