const INSURANCE_VALUE_BY_ITEM_TYPE = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
} as const satisfies Record<InsurableItemType, number>;

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

const insuranceValueOf = (item: Item): number =>
  INSURANCE_VALUE_BY_ITEM_TYPE[item.type as InsurableItemType];

const capOf = (items: Item[]): number =>
  CAP_MULTIPLE_OF_INSURANCE_SUM *
  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);

const payoutFor = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const claimResult = (
  step: Extract<Step, { op: "claim" }>,
  steps: Step[],
): StepResult => {
  const policy = steps[step.policy];
  if (policy?.op !== "quote") throw new Error("claim references no policy");
  const payout = step.incident.damages.reduce(
    (sum, damage) => sum + payoutFor(damage),
    0,
  );
  return { payout, remainingCap: capOf(policy.items) - payout };
};

const runStep = (
  step: Step,
  context: QuoteContext,
  steps: Step[],
): StepResult =>
  step.op === "quote"
    ? { premium: quotePremium(step.items, context) }
    : claimResult(step, steps);

