type RemainingCapByPolicy = Map<number, number>;

const remainingCapFor = (
  step: Extract<Step, { op: "claim" }>,
  insured: Item[],
  remainingCaps: RemainingCapByPolicy,
): number => remainingCaps.get(step.policy) ?? policyCapOf(insured);

const claimResult = (
  step: Extract<Step, { op: "claim" }>,
  steps: Step[],
  remainingCaps: RemainingCapByPolicy,
): StepResult => {
  const insured = policyOf(step, steps).items;
  const desiredPayout = roundOutgoingInMHPCOsFavour(
    sumOf(step.incident.damages, (damage) => reimbursementFor(damage, insured)),
  );
  const capBeforeClaim = remainingCapFor(step, insured, remainingCaps);
  const payout = Math.min(desiredPayout, capBeforeClaim);
  const remainingCap = capBeforeClaim - payout;
  remainingCaps.set(step.policy, remainingCap);
  return { payout, remainingCap };
};

const runStep = (
  step: Step,
  context: QuoteContext,
  steps: Step[],
  remainingCaps: RemainingCapByPolicy,
): StepResult =>
  step.op === "quote"
    ? { premium: quotePremium(step.items, context) }
    : claimResult(step, steps, remainingCaps);

const countQuotesBefore = (steps: Step[], index: number): number =>
  steps.slice(0, index).filter((step) => step.op === "quote").length;

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
  const remainingCaps: RemainingCapByPolicy = new Map();
  return {
    results: steps.map((step, index) =>
      runStep(
        step,
        { customer, previousQuotes: countQuotesBefore(steps, index) },
        steps,
        remainingCaps,
      ),
    ),
  };
};

