    customer: { yearsWithMHPCO: 5 },
    steps: [
      {
        op: "quote",
        items: [
          {
            type: "amulet",
            material: "silver",
            enchantment: 2,
            cursed: false,
          },
        ],
      },
      {
        op: "claim",
        policy: 0,
        incident: {
          cause: "fire",
          damages: [{ itemType: "amulet", amount: 200 }],
        },
      },
    ],
  });

  expect(JSON.parse(stdout)).toEqual({
    results: [
      { premium: 59 },
      { payout: 100, remainingCap: 1100 },
    ],
  });
});

